PRED = {}
def add(cid, tl, sys_, text, basis, conf, trig=None):
    PRED[cid] = dict(case_id=cid, prediction_text=text, basis=f"{tl}\nsystems_used: {sys_}\n{basis}", confidence=conf, trigger=trig if trig is not None else {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""})
def ly(cid, tl, sys_, text, basis, conf, cm, ru, di, reason):
    add(cid, tl, sys_, text, basis, conf, {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason})
